import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { inferRevealVariant, staggerDelay as stagger } from './inferReveal.js';

export default function MotionReveal({
  as: Tag = 'div',
  variant = 'auto',
  role,
  delay = 0,
  strong = false,
  immediate = false,
  className = '',
  children,
  style,
  ...props
}) {
  const ref = useRef(null);
  const [dir, setDir] = useState(variant === 'auto' ? 'up' : variant);
  const [visible, setVisible] = useState(!!immediate);
  const [settled, setSettled] = useState(!!immediate);

  useLayoutEffect(() => {
    if (variant !== 'auto') {
      setDir(variant);
      return;
    }
    if (ref.current) setDir(inferRevealVariant(ref.current, role));
  }, [variant, role]);

  useEffect(() => {
    const el = ref.current;
    if (!el) return undefined;

    if (immediate || window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      setVisible(true);
      setSettled(true);
      return undefined;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.12, rootMargin: '0px 0px -10% 0px' }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [immediate]);

  useEffect(() => {
    if (!visible || settled) return undefined;
    const duration = strong ? 720 : 560;
    const timer = window.setTimeout(() => setSettled(true), duration + delay + 40);
    return () => window.clearTimeout(timer);
  }, [visible, settled, delay, strong]);

  const classes = [
    'mmc-reveal',
    `mmc-reveal--${dir}`,
    strong ? 'mmc-reveal--strong' : '',
    visible ? 'is-in' : '',
    settled ? 'is-ready' : '',
    className,
  ].filter(Boolean).join(' ');

  return (
    <Tag
      ref={ref}
      className={classes}
      {...props}
      style={{ '--mmc-reveal-delay': `${delay}ms`, ...style }}
    >
      {children}
    </Tag>
  );
}

export function staggerDelay(index, step = 65, base = 0) {
  return stagger(index, step, base);
}
